import{_ as a,o as r,c as t,ag as i}from"./chunks/framework.CrXGS008.js";const y=JSON.parse('{"title":"nay_lib","description":"","frontmatter":{},"headers":[],"relativePath":"nay-lib/index.md","filePath":"nay-lib/index.md"}'),s={name:"nay-lib/index.md"};function n(o,e,l,d,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="nay-lib" tabindex="-1">nay_lib <a class="header-anchor" href="#nay-lib" aria-label="Permalink to &quot;nay_lib&quot;">​</a></h1><p><code>nay_lib</code> is the shared library behind every Nayretis script. You get it with every purchase, install it once, and every Nayretis script you add uses it.</p><h2 id="what-it-gives-you" tabindex="-1">What it gives you <a class="header-anchor" href="#what-it-gives-you" aria-label="Permalink to &quot;What it gives you&quot;">​</a></h2><ul><li><strong>One settings panel</strong>, <code>/nay</code>, for every Nayretis script. Settings are stored in your database and applied to every player as soon as you save. See <a href="/nay-lib/panel">/nay panel</a>.</li><li><strong>Permissions</strong> by ACE, Discord, Steam, FiveM or license identifier. See <a href="/nay-lib/permissions">Permissions</a>.</li><li><strong>Six languages</strong>: English, French, Spanish, Portuguese, Polish and German. A missing translation falls back to English.</li><li><strong>Framework bridge</strong>: ESX Legacy, QBCore, QBox and ox_core detected automatically, with their inventories, targets and notifications. See <a href="/bridge/">Bridge</a>.</li><li><strong>HTTP API</strong> for your website, dashboard or Discord bot, off by default. See <a href="/nay-lib/api">HTTP API</a>.</li><li><strong>Webhooks</strong>, including Discord messages, for script events. See <a href="/nay-lib/webhooks">Webhooks</a>.</li><li><strong>Audit log</strong> of every change made in game, from the console or through the API. See <a href="/nay-lib/audit">Audit log</a>.</li><li>Nayretis notifications, text prompts and progress bars, shared by every script.</li></ul><h2 id="requirements-and-start-order" tabindex="-1">Requirements and start order <a class="header-anchor" href="#requirements-and-start-order" aria-label="Permalink to &quot;Requirements and start order&quot;">​</a></h2><p>The only dependency is <a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>. Start <code>nay_lib</code> after your framework, inventory and target resources, and before every Nayretis script:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span></code></pre></div><p>Tables are created on the first start. Server options that live in <code>server.cfg</code> are listed on the <a href="/nay-lib/convars">Convars</a> page.</p>`,8)])])}const g=a(s,[["render",n]]);export{y as __pageData,g as default};
